WITH cleaned AS (SELECT *, GREATEST(revenue, units) AS greatest_revenue_units, LEAST(units, revenue) AS least_units_revenue FROM store_sales WHERE sale_date > DATE '2023-06-19'), filtered AS (SELECT *, greatest_revenue_units - least_units_revenue AS greatest_revenue_units_minus_least_units_revenue, GREATEST(greatest_revenue_units, least_units_revenue) AS greatest_greatest_revenue_units_least_units_revenue FROM cleaned WHERE revenue < 3500), cleaned_store_sales AS (SELECT *, ROUND(greatest_revenue_units_minus_least_units_revenue, 1) AS greatest_revenue_units_minus_least_units_revenue_rounded FROM filtered WHERE greatest_greatest_revenue_units_least_units_revenue < 71), remaining_keys AS (SELECT product_id, store_id FROM cleaned_store_sales INTERSECT ALL SELECT product_id, store_id FROM store_sales WHERE product_id IN (2, 3, 7)), verified AS (SELECT s.* FROM cleaned_store_sales s INNER JOIN remaining_keys k ON s.product_id = k.product_id AND s.store_id = k.store_id) SELECT store_id, product_id, sale_date, units, least_units_revenue, greatest_greatest_revenue_units_least_units_revenue FROM verified ORDER BY least_units_revenue DESC;
